// FocusBro brand assets — the one mark, served everywhere it appears.
//
// The mark: a ring that loops back on itself with a check breaking out through
// the gap — "the check-in that follows up". Amber (#f2b45a) on ink (#0d0f12).
// The PNGs are rendered from the same geometry (scripts/brand/render.mjs) and
// embedded so the Worker serves real raster icons with no asset binding:
// installable-PWA checks and social link previews both reject SVG.
//
// Pure, dependency-free, Worker-safe.

const GLYPH = (stroke) =>
  '<path d="M25 16.5A9 9 0 1 1 19.8 7.8" fill="none" stroke="' + stroke + '" stroke-width="2.6" stroke-linecap="round"/>' +
  '<path d="M11.4 15.6l3.9 3.9 8.6-9.3" fill="none" stroke="' + stroke + '" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/>';

/** The rounded-square mark as a standalone SVG (favicon, JSON-LD logo). */
export const MARK_SVG =
  '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32">' +
  '<rect width="32" height="32" rx="9" fill="#f2b45a"/>' + GLYPH('#1b1305') + '</svg>';

/** Brand colours the manifest and meta tags share with the page tokens. */
export const BRAND = Object.freeze({ ink: '#0d0f12', amber: '#f2b45a' });

function decode(b64) {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

const PNG_B64 = {
  'icon-192.png': '',
  'icon-512.png': '',
  'og.png': '',
};

/**
 * Serve one brand asset by file name.
 * @param {string} name - `mark.svg` | `icon-192.png` | `icon-512.png` | `og.png`
 * @returns {Response|null} null when the name is not a brand asset
 */
export function brandAssetResponse(name) {
  const headers = { 'Cache-Control': 'public, max-age=86400', 'Access-Control-Allow-Origin': '*' };
  if (name === 'mark.svg') {
    return new Response(MARK_SVG, { status: 200, headers: { ...headers, 'Content-Type': 'image/svg+xml' } });
  }
  const b64 = PNG_B64[name];
  if (!b64) return null;
  return new Response(decode(b64), { status: 200, headers: { ...headers, 'Content-Type': 'image/png' } });
}
